#if FUEL_PILGRIM
// cc_fuel5: fu2_memcmp (equality-only) for the 50x65 Pilgrimage layout (id 2); other layouts keep std::memcmp.
inline int z195_mc(int id, const void* a, const void* b, std::size_t n) { return id == 2 ? fu2_memcmp(a, b, n) : std::memcmp(a, b, n); }
#define Z195_MC(a, b, n) z195_mc(r.id, a, b, n)
#else
#define Z195_MC(a, b, n) std::memcmp(a, b, n)
#endif
inline int detect() {
 const int w=map::width(),h=map::height(),n=static_cast<int>(draft::team_size());
 for (const auto& r:layouts) {
  if (w!=r.w || h!=r.h || n!=r.n || static_cast<int>(map::symmetry())!=r.sym) continue;
  const std::size_t bytes=bitboard::raw_buffer_size();
  if(bytes!=r.words*sizeof(std::uint64_t))continue;
  const bitboard* bb[]={&map::walls(),&map::holes(),&map::bushes(),&map::altars()};
  bool same=true;
  for(int i=0;i<4;++i)if(Z195_MC(bb[i]->ptr(),r.masks[i],bytes)) {same=false;break;}
  if(!same)continue;
  // The two absolute spawn masks are unchanged when playing side B.
  const auto* own=map::spawn_region(team::ally).ptr();
  const auto* foe=map::spawn_region(team::enemy).ptr();
  if(!((!Z195_MC(own,r.masks[4],bytes)&&!Z195_MC(foe,r.masks[5],bytes)) ||
       (!Z195_MC(own,r.masks[5],bytes)&&!Z195_MC(foe,r.masks[4],bytes))))continue;
  std::vector<std::uint32_t> camps(r.count);std::uint32_t count=0;
  detail::check(detail::sdk_map_camp_layout(camps.data(),static_cast<std::uint32_t>(camps.size()),&count));
  if(count!=r.count || Z195_MC(camps.data(),r.camps,r.count*sizeof(std::uint32_t)))continue;
  return r.id;
 }
 return 0;
}

